SELECT COUNT(1)
FROM trade_order
WHERE buyer_id = #{buyerId}

SELECT COALESCE(SUM(quantity), 0)
FROM trade_order
WHERE activity_id = #{activityId}
  AND buyer_id = #{buyerId}
  AND status IN ('PENDING_PAYMENT', 'PAID')

mapper.update:
UPDATE trade_activity
SET available_stock = available_stock - #{quantity},
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{activityId}
  AND available_stock >= #{quantity}
  AND version = #{version}

UPDATE trade_activity
SET available_stock = available_stock + #{quantity},
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{activityId}
  AND version = #{version}

UPDATE trade_order
SET status = 'PAID',
    pay_channel = #{payChannel},
    pay_time = #{now},
    updated_at = #{now},
    version = version + 1
WHERE order_no = #{orderNo}
  AND buyer_id = #{buyerId}
  AND status = 'PENDING_PAYMENT'
  AND expire_at > #{now}

UPDATE trade_order
SET status = 'CLOSED',
    close_time = #{now},
    close_reason = #{closeReason},
    updated_at = #{now},
    version = version + 1
WHERE order_no = #{orderNo}
  AND buyer_id = #{buyerId}
  AND status = 'PENDING_PAYMENT'
  AND expire_at > #{now}

UPDATE outbox
SET status = 'failed',
    retry_count = retry_count + 1,
    last_error = #{lastError}
WHERE id = #{id}
